var o=[{title:`Semana um: aprenda a rotina`,text:`Escolha duas sessões curtas de corpo inteiro e faça caminhadas fáceis nos outros dias se tiver vontade. Pratique os padrões básicos de agachamento, dobra de anca, empurrar, puxar e core com movimentos que se adaptem ao seu equipamento e ao seu corpo. Uma primeira sessão pode ser uma ou duas séries de vários exercícios.`},{title:`Semanas dois a quatro: repita e observe`,text:`Mantenha os mesmos exercícios e depois acrescente devagar repetições, um pouco de carga ou uma série extra se estiver a recuperar bem. Pequenos aumentos que consegue manter ajudam a ganhar confiança. Não leia cada sensação nova ou dor muscular como razão para mudar o plano todo.`},{title:`Exemplo`,text:`À segunda e à quinta, faça agachamentos controlados com cadeira, remadas com apoio, flexões na parede e uma manutenção curta de core. Acrescente uma caminhada confortável noutro dia. Se um movimento for demasiado difícil, escolha uma versão mais fácil. Se for muito fácil, torne-o mais difícil gradualmente mantendo o controlo.`},{title:`O que esperar no início`,text:`Os primeiros ganhos de força costumam vir de melhor competência e coordenação entre os nervos e os músculos, e as mudanças físicas mostram-se mais com o tempo. Faltar a um treino não apaga o seu progresso. Basta retomar na sessão planeada seguinte.`},{title:`Usar o TrainUp`,text:`Defina com honestidade o seu nível de condição física no Perfil, juntamente com o equipamento que tem e a duração da sessão. Depois de cada treino, avalie o esforço (RPE). O seu plano só muda quando o gera de novo, e nunca com base em menos de 3 treinos. Se os seus últimos 4 tiverem sido fáceis (RPE 5 ou menos) e completos, o plano seguinte fica um passo mais difícil.`}];var s=[{label:`Orientações práticas do ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`},{label:`NHS: caminhar para a saúde`,url:`https://www.nhs.uk/live-well/exercise/walking-for-health/`}];var r={sections:o,sources:s};export{r as default,o as sections,s as sources};